          listEl.prepend(buildTodoItem(todo));
        } catch (err) {
          if (err instanceof ApiError) showMessage(err.message, "error");
          else showMessage("Failed to add todo.", "error");
        }
      });
    });

    prevBtn.addEventListener("click", () => {
      currentPage.offset = Math.max(0, currentPage.offset - currentPage.limit);
      loadTodos();
    });

    nextBtn.addEventListener("click", () => {
      currentPage.offset += currentPage.limit;
      loadTodos();
    });

    filterRadios.forEach(radio => {
      radio.addEventListener("change", () => {
        currentFilter = radio.value;
        currentPage.offset = 0;
        loadTodos();
      });
    });

    signoutBtn.addEventListener("click", () => {
      clearToken();
      location.href = "login.html";
    });

    await loadUser();
    await loadTodos();
  </script>
</body>
</html>
